mapper.select:
SELECT user_id, enabled, updated_at
FROM recommendation_user_setting
WHERE user_id = #{userId}

mapper.update:
UPDATE recommendation_user_setting
SET enabled = #{enabled}, updated_at = #{updatedAt}
WHERE user_id = #{userId}

mapper.select:
SELECT id, user_id, mode, algorithm_version, signal_count,
       source_fingerprint, generated_at, expires_at
FROM recommendation_batch
WHERE user_id = #{userId}
  AND source_fingerprint = #{sourceFingerprint}
  AND expires_at > #{now}
ORDER BY id DESC
LIMIT 1
